package com.bank.ledger;

import java.math.BigDecimal;
import java.nio.file.*;
import java.util.logging.*;

public class MappedLedgerDemo {
    private static final Logger log = Logger.getLogger(MappedLedgerDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        Path path = Files.createTempFile("ledger", ".dat");
        // 2 accounts, 8 bytes each (a long of paise).
        var ledger = new MappedLedger(path, 2);

        ledger.setBalance(0, new BigDecimal("1000000.00"));  // Rajesh SAV2001
        ledger.setBalance(1, new BigDecimal("250000.00"));   // Priya  CUR3001
        ledger.flush();  // force(): dirty pages written to disk — durable

        log.info(() -> "Mapped read Rajesh: Rs." + ledger.getBalance(0));
        log.info(() -> "Mapped read Priya : Rs." + ledger.getBalance(1));

        // Settlement update, then force for durability before reporting success.
        BigDecimal newRajesh = ledger.getBalance(0).subtract(new BigDecimal("50000.00"));
        ledger.setBalance(0, newRajesh);
        ledger.flush();
        log.info(() -> "After Rs.50000 debit, Rajesh: Rs." + ledger.getBalance(0));

        ledger.close();  // deterministic unmap via Arena (FFM API)
        Files.deleteIfExists(path);  // safe to delete: mapping released
        log.info("Ledger unmapped and temp file deleted");
    }
}

// ─── Would be in store/MappedLedger.java ───
class MappedLedger implements AutoCloseable {
    private static final long RECORD = Long.BYTES;  // 8 bytes per account (paise)
    private final java.lang.foreign.Arena arena;
    private final java.lang.foreign.MemorySegment segment;  // the mapped region
    private final java.nio.channels.FileChannel channel;
    private final long capacity;

    MappedLedger(Path path, long capacity) throws java.io.IOException {
        this.capacity = capacity;
        this.channel = java.nio.channels.FileChannel.open(path,
                StandardOpenOption.READ, StandardOpenOption.WRITE, StandardOpenOption.CREATE);
        this.arena = java.lang.foreign.Arena.ofConfined();
        // FFM map: whole file as one MemorySegment, deterministic unmap on close.
        this.segment = channel.map(
                java.nio.channels.FileChannel.MapMode.READ_WRITE, 0, capacity * RECORD, arena);
    }

    void setBalance(long index, BigDecimal rupees) {
        checkIndex(index);
        long paise = rupees.movePointRight(2).longValueExact();
        segment.setAtIndex(java.lang.foreign.ValueLayout.JAVA_LONG, index, paise);
    }

    BigDecimal getBalance(long index) {
        checkIndex(index);
        long paise = segment.getAtIndex(java.lang.foreign.ValueLayout.JAVA_LONG, index);
        return BigDecimal.valueOf(paise, 2);
    }

    void flush() throws java.io.IOException {
        channel.force(true);  // flush dirty mapped pages + metadata to disk (durable)
    }

    private void checkIndex(long index) {
        if (index < 0 || index >= capacity) throw new IndexOutOfBoundsException("index " + index);
    }

    @Override public void close() throws java.io.IOException {
        arena.close();    // unmap deterministically
        channel.close();
    }
}
